import { describe, expect, it } from "vitest";
import type { MotionDefinition, TrackDefinition } from "../../../src/contract/v5";
import { AUTHORED } from "../../../src/runtime/value-state";
import { invert, planCommit, type CommitDocument } from "../../../src/runtime/commit-plan";
import { runPlan, type PlanPorts, type PlanStaged } from "../../../src/runtime/run-plan";
const M = (id: string): MotionDefinition => ({ id, trigger: { type: "manual" }, tracks: [] });
const ent = (track: TrackDefinition, motionId?: string) => ({ track, motionId, valueState: AUTHORED });
const doc = (tracks: readonly [string, ReturnType<typeof ent>][], motions: readonly [string, { definition: MotionDefinition }][] = []): CommitDocument => ({ tracks: new Map(tracks), motions: new Map(motions) });
function ports(log: string[], failures: Record<string, unknown> = {}, staged?: PlanStaged): PlanPorts {
  const call = (name: string, value?: unknown) => { log.push(name); if (Object.hasOwn(failures, name)) throw failures[name]; return value; };
  return {
    createMotion: x => { call(`create:${x.id}`); }, destroyMotion: id => { call(`destroy:${id}`); },
    compileTrack: (_x, id) => { call(`compile:${id}`); }, stageTrack: (_x, id) => { call(`stage:${id}`); return staged; },
    replaceMotionTrack: (_m, id) => { call(`retarget:${id}`); }, commitStaged: (_x, id) => { call(`commit:${id}`); },
    rollbackStaged: (_x, id) => { call(`rollback:${id}`); }, disposeTrack: id => { call(`dispose:${id}`); },
    evictNode: id => { call(`evict:${id}`); }, mountNode: id => { call(`mount:${id}`); },
    addMotionTrack: (_m, id) => { call(`add:${id}`); }, removeMotionTrack: (_m, id) => { call(`remove:${id}`); },
    assertLive: () => { call("live"); }, accept: () => { call("accept"); }, adopt: () => { call("adopt"); },
    publish: ids => { call(`publish:${ids.join(",")}`); },
  };
}
function completePlan(): { plan: ReturnType<typeof planCommit>; before: CommitDocument } {
  const before = doc(
    [["hero/old", ent({ id: "old", duration: 1 }, "hero")], ["gone/obsolete", ent({ id: "obsolete" }, "gone")], ["~/free", ent({ id: "free" })]],
    [["hero", { definition: M("hero") }], ["gone", { definition: M("gone") }]],
  );
  const after = doc(
    [["hero/old", ent({ id: "old", duration: 2 }, "hero")], ["new/child", ent({ id: "child" }, "new")]],
    [["hero", { definition: M("hero") }], ["new", { definition: M("new") }]],
  );
  return { before, plan: planCommit(before, after, { needsBuild: new Set(["hero/old"]), readers: new Map([["~/free", ["hero/reader"]]]) }) };
}
describe("runPlan", () => {
  it("applies every planned variant, asserts after effects, accepts, adopts, settles, then publishes", () => {
    const { plan } = completePlan(), log: string[] = [];
    runPlan(plan, ports(log));
    expect(log).toEqual(["create:new", "live", "stage:hero/old", "live", "retarget:hero/old", "live", "compile:new/child", "live", "accept", "adopt", "evict:gone/obsolete", "dispose:gone/obsolete", "remove:gone/obsolete", "evict:~/free", "dispose:~/free", "destroy:gone", "commit:hero/old", "add:new/child", "mount:new/child", "publish:hero/reader,new/child"]);
  });
  it("records only successful effects and rolls them back in applied order", () => {
    const before = doc([], []), after = doc([["a", ent({ id: "a" })], ["b", ent({ id: "b" })]], []);
    const plan = planCommit(before, after, { needsBuild: new Set(), readers: new Map() });
    const log: string[] = [];
    expect(() => runPlan(plan, ports(log, { accept: new Error("reject") }))).toThrow("reject");
    expect(log).toEqual(["compile:a", "live", "compile:b", "live", "accept", "dispose:a", "dispose:b"]);
  });
  it("rolls back when assertLive rejects a successful effect", () => {
    const plan = planCommit(doc([], []), doc([["a", ent({ id: "a" })]], []), { needsBuild: new Set(), readers: new Map() });
    const failure = new Error("disposed");
    const log: string[] = [];
    expect(() => runPlan(plan, ports(log, { live: failure }))).toThrow(failure);
    expect(log).toEqual(["compile:a", "live", "dispose:a"]);
  });
  it("continues settlement and preserves settle-before-publish error order", () => {
    const before = doc([["a", ent({ id: "a" })]], []), plan = planCommit(before, doc([], []), { needsBuild: new Set(), readers: new Map() });
    const first = new Error("dispose"), second = new Error("publish"), log: string[] = [];
    let thrown: unknown;
    try { runPlan(plan, ports(log, { "dispose:a": first, "publish:": second })); } catch (error) { thrown = error; }
    expect(log).toEqual(["evict:a", "dispose:a", "publish:"]);
    expect(thrown).toBeInstanceOf(AggregateError);
    expect((thrown as AggregateError).errors).toEqual([first, second]);
  });
  it("runs every effect variant through the same runner", () => {
    const create = planCommit(doc([], []), doc([], [["hero", { definition: M("hero") }]]), { needsBuild: new Set(), readers: new Map() }).effects[0]!;
    const destroy = invert(create)!;
    const compile = planCommit(doc([], []), doc([["hero/track", ent({ id: "track" })]], []), { needsBuild: new Set(), readers: new Map() }).effects[0]!;
    const dispose = invert(compile)!;
    const staged = planCommit(doc([["hero/track", ent({ id: "track" }, "hero")]], []), doc([["hero/track", ent({ id: "track", duration: 1 }, "hero")]], []), { needsBuild: new Set(["hero/track"]), readers: new Map() }).effects;
    const stage = staged[0]!, rollback = invert(stage)!, retarget = staged[1]!;
    const log: string[] = [];
    runPlan({ effects: [create, destroy, compile, dispose, stage, rollback, retarget], settle: [], touched: [] }, ports(log));
    expect(log).toEqual(["create:hero", "live", "destroy:hero", "live", "compile:hero/track", "live", "dispose:hero/track", "live", "stage:hero/track", "live", "rollback:hero/track", "live", "retarget:hero/track", "live", "accept", "adopt"]);
  });
  it("records successful effects, passes undefined stages, and rolls back in order", () => {
    const before = doc([["a", ent({ id: "a" }, "hero")]], []), after = doc([["a", ent({ id: "a", duration: 1 }, "hero")]], []);
    const plan = planCommit(before, after, { needsBuild: new Set(["a"]), readers: new Map() });
    const log: string[] = [];
    runPlan(plan, ports(log));
    expect(log).toEqual(["stage:a", "live", "retarget:a", "live", "accept", "adopt", "commit:a", "publish:a"]);
    const failed: string[] = [];
    expect(() => runPlan(plan, ports(failed, { accept: new Error("reject") }))).toThrow("reject");
    expect(failed).toEqual(["stage:a", "live", "retarget:a", "live", "accept", "rollback:a", "retarget:a"]);
  });
});
